// Remove duplicate consecutive vertices
    if (polygon.exterior.size() > 2) {
        auto& vertices = polygon.exterior;
        for (size_t i = 1; i < vertices.size() - 1; ) {
            if (vertices[i] == vertices[i-1] || vertices[i] == vertices[i+1]) {
                vertices.erase(vertices.begin() + i);
            } else {
                ++i;
            }
        }
    }
    // Similar simplification for holes
    for (auto& hole : polygon.holes) {
        if (hole.exterior.size() > 2) {
            auto& vertices = hole.exterior;
            for (size_t i = 1; i < vertices.size() - 1; ) {
                if (vertices[i] == vertices[i-1] || vertices[i] == vertices[i+1]) {
                    vertices.erase(vertices.begin() + i);
                } else {
                    ++i;
                }
            }
        }
    }

